changeSet.sql:
UPDATE analytics_report_template
   SET spec_json = replace(
           replace(spec_json, '"reportType":"fixed-screen"', '"reportType":"fixed-table"'),
           '"displayType":"screen"',
           '"displayType":"table"'
       ),
       presentation_schema_json = '{"primary":"table","layout":"fixed-report-table","visualization":"bi-only"}',
       updated_at = ${now}
 WHERE template_code LIKE 'PRS-FLOWERBIZ-%'
   AND archived = false;
